css:
/* Job Requisition Summary — manager-facing one-pager.
   Kept to borders + light fills so it survives wkhtmltopdf and a mono printer. */

.jr {
	font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
	color: #1f272e;
	font-size: 11px;
	line-height: 1.45;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.jr * {
	box-sizing: border-box;
}

/* ---------- masthead ---------- */

.jr-head {
	border: 1px solid #d5dbe1;
	border-top: 3px solid #1f4e79;
	border-radius: 3px;
	padding: 12px 14px;
	margin-bottom: 14px;
	background: #f7f9fb;
}

.jr-head-top {
	display: table;
	width: 100%;
}

.jr-head-left {
	display: table-cell;
	vertical-align: top;
}

.jr-head-right {
	display: table-cell;
	vertical-align: top;
	text-align: right;
	white-space: nowrap;
}

.jr-eyebrow {
	font-size: 9px;
	letter-spacing: 1.4px;
	text-transform: uppercase;
	color: #6b7a88;
	margin-bottom: 2px;
}

.jr-title {
	font-size: 17px;
	font-weight: 700;
	color: #1f4e79;
	line-height: 1.2;
}

.jr-subtitle {
	font-size: 11px;
	color: #55636f;
	margin-top: 2px;
}

.jr-id {
	font-size: 12px;
	font-weight: 700;
	color: #1f272e;
}

.jr-pill {
	display: inline-block;
	margin-top: 5px;
	padding: 3px 10px;
	border-radius: 11px;
	font-size: 9.5px;
	font-weight: 700;
	letter-spacing: 0.6px;
	text-transform: uppercase;
	border: 1px solid #b9c2cb;
	background: #eef1f4;
	color: #46525e;
}

.jr-pill-green {
	border-color: #9ed0ae;
	background: #e9f7ee;
	color: #1e6b39;
}

.jr-pill-amber {
	border-color: #e6c98a;
	background: #fdf5e4;
	color: #8a5f10;
}

.jr-pill-red {
	border-color: #e8aeae;
	background: #fdeeee;
	color: #9c2b2b;
}

.jr-pill-blue {
	border-color: #a8c4e0;
	background: #ecf3fa;
	color: #1f4e79;
}

/* ---------- headline stats ---------- */

.jr-stats {
	width: 100%;
	border-collapse: separate;
	border-spacing: 6px 0;
	margin: 12px 0 14px;
	table-layout: fixed;
}

.jr-stats td {
	border: 1px solid #d5dbe1;
	border-radius: 3px;
	background: #ffffff;
	padding: 8px 10px;
	text-align: center;
	vertical-align: middle;
}

.jr-stat-value {
	font-size: 16px;
	font-weight: 700;
	color: #1f4e79;
	line-height: 1.1;
}

.jr-stat-label {
	font-size: 8.5px;
	letter-spacing: 0.9px;
	text-transform: uppercase;
	color: #6b7a88;
	margin-top: 3px;
}

/* ---------- sections ---------- */

.jr-section {
	margin-bottom: 13px;
	page-break-inside: avoid;
}

.jr-section-title {
	font-size: 10px;
	font-weight: 700;
	letter-spacing: 1.1px;
	text-transform: uppercase;
	color: #1f4e79;
	border-bottom: 1px solid #1f4e79;
	padding-bottom: 3px;
	margin-bottom: 7px;
}

/* label / value grid — two pairs per row */

.jr-grid {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}

.jr-grid td {
	padding: 4px 8px 4px 0;
	vertical-align: top;
	border-bottom: 1px solid #eef1f4;
}

.jr-label {
	width: 17%;
	color: #6b7a88;
	font-size: 9.5px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.jr-value {
	width: 33%;
	font-weight: 600;
	color: #1f272e;
	word-wrap: break-word;
}

/* ---------- data tables ---------- */

.jr-table {
	width: 100%;
	border-collapse: collapse;
	font-size: 10px;
}

.jr-table th {
	background: #eef1f4;
	border: 1px solid #d5dbe1;
	padding: 5px 7px;
	text-align: left;
	font-size: 9px;
	letter-spacing: 0.6px;
	text-transform: uppercase;
	color: #46525e;
	font-weight: 700;
}

.jr-table td {
	border: 1px solid #d5dbe1;
	padding: 5px 7px;
	vertical-align: top;
}

.jr-table tbody tr:nth-child(even) td {
	background: #fafbfc;
}

.jr-num {
	text-align: right;
	white-space: nowrap;
}

.jr-center {
	text-align: center;
}

/* ---------- prose / chips ---------- */

.jr-prose {
	border: 1px solid #e3e8ec;
	border-left: 3px solid #b9c2cb;
	border-radius: 2px;
	background: #fbfcfd;
	padding: 8px 10px;
}

/* plain-text fields keep their own line breaks; rich text brings its own tags */
.jr-pre {
	white-space: pre-wrap;
}

.jr-prose p:last-child {
	margin-bottom: 0;
}

.jr-chip {
	display: inline-block;
	border: 1px solid #c9d3dc;
	border-radius: 10px;
	background: #f2f6f9;
	padding: 2px 9px;
	margin: 0 4px 4px 0;
	font-size: 9.5px;
	font-weight: 600;
	color: #34424e;
}

.jr-muted {
	color: #8a97a3;
	font-style: italic;
}

/* ---------- sign-off ---------- */

.jr-sign {
	width: 100%;
	border-collapse: separate;
	border-spacing: 10px 0;
	table-layout: fixed;
	margin-top: 18px;
	page-break-inside: avoid;
}

.jr-sign td {
	border: 1px solid #d5dbe1;
	border-radius: 3px;
	padding: 8px 10px 6px;
	vertical-align: top;
	height: 66px;
}

.jr-sign-role {
	font-size: 9px;
	letter-spacing: 0.8px;
	text-transform: uppercase;
	color: #6b7a88;
}

.jr-sign-name {
	font-size: 10.5px;
	font-weight: 600;
	margin-top: 2px;
}

.jr-sign-line {
	border-top: 1px dotted #9aa6b1;
	margin-top: 26px;
	padding-top: 3px;
	font-size: 8.5px;
	color: #8a97a3;
}

.jr-foot {
	margin-top: 12px;
	padding-top: 6px;
	border-top: 1px solid #e3e8ec;
	font-size: 8.5px;
	color: #8a97a3;
	display: table;
	width: 100%;
}

.jr-foot-left {
	display: table-cell;
	text-align: left;
}

.jr-foot-right {
	display: table-cell;
	text-align: right;
}

/* totals row on the region roll-up */
.jr-table tbody tr.jr-total td {
	background: #eef1f4;
	font-weight: 700;
	border-top: 1.5px solid #b9c2cb;
}

/* rich text (Text Editor) arrives with its own markup — give it room, not a box */
.jr-rich {
	font-size: 10.5px;
}

.jr-rich table {
	width: 100%;
	border-collapse: collapse;
}

.jr-rich table td,
.jr-rich table th {
	border: 1px solid #d5dbe1;
	padding: 4px 7px;
	vertical-align: top;
}

.jr-rich p:last-child {
	margin-bottom: 0;
}

/* a job description can run past one page — let it break instead of overflowing */
.jr-section-flow {
	page-break-inside: auto;
}

html:
{#- Job Requisition Summary — a manager-facing read of the requisition.

    Two rules run through the whole template:
      * nothing empty prints — pairs are filtered before they are laid out, so a
        thin requisition prints short instead of printing a page of blank labels;
      * links print as names, not IDs — a manager reads "Gopal Kumar", not PP0004,
        so every Link value goes through `t()` and comes back as its title field. -#}

{%- macro t(dt, value) -%}
	{%- if value -%}
		{%- set title_field = frappe.get_meta(dt).get_title_field() -%}
		{%- if title_field == "name" -%}
			{{ value }}
		{%- else -%}
			{{ frappe.db.get_value(dt, value, title_field) or value }}
		{%- endif -%}
	{%- endif -%}
{%- endmacro -%}

{%- macro grid(pairs) -%}
	{%- set rows = [] -%}
	{%- for p in pairs if p[1] not in (None, "", 0) -%}
		{%- set _skip = rows.append(p) -%}
	{%- endfor -%}
	{%- if rows -%}
	<table class="jr-grid">
		{%- for chunk in rows | batch(2) -%}
		<tr>
			{%- for p in chunk -%}
			<td class="jr-label">{{ p[0] }}</td>
			<td class="jr-value">{{ p[1] }}</td>
			{%- endfor -%}
			{%- if chunk | length == 1 -%}
			<td class="jr-label"></td><td class="jr-value"></td>
			{%- endif -%}
		</tr>
		{%- endfor -%}
	</table>
	{%- endif -%}
{%- endmacro -%}

{%- set pill = {
	"Draft": "",
	"Approval Pending": "jr-pill-amber",
	"Approved Draft": "jr-pill-blue",
	"Approved Active": "jr-pill-green",
	"Rejected": "jr-pill-red",
	"Cancelled": "jr-pill-red",
	"On Hold": "jr-pill-amber",
	"Archived": "",
	"Auto Archived": ""
}.get(doc.status, "") -%}

{%- set positions = doc.get("custom_position_details") or [] -%}
{%- set regions = doc.get("custom_regions") or [] -%}
{%- set quals = doc.get("custom_qualifications") or [] -%}
{%- set skills = doc.get("custom_skills") or [] -%}
{%- set jd_details = doc.get("custom_jd_details") or [] -%}
{%- set candidates = doc.get("custom_pre_screened_candidates") or [] -%}

{%- set tot = namespace(openings=0, employees=0, requisitions=0, live=0) -%}
{%- for r in regions -%}
	{%- set tot.openings = tot.openings + (r.no_of_openings or 0) -%}
	{%- set tot.employees = tot.employees + (r.active_employees or 0) -%}
	{%- set tot.requisitions = tot.requisitions + (r.active_requisitions or 0) -%}
	{%- set tot.live = tot.live + (r.active_openings or 0) -%}
{%- endfor -%}
{%- set openings = doc.no_of_positions or tot.openings or (positions | length) -%}

{%- set department = t("Department", doc.department) -%}
{%- set requester_dept = t("Department", doc.requested_by_dept) -%}
{%- set requested_by = doc.requested_by_name or t("Employee", doc.requested_by) -%}
{%- set hiring_lead = t("Employee", doc.get("custom_hiring_lead")) -%}
{%- set recruiter = t("User", doc.get("custom_assign_to_recruiter")) -%}
{%- set location = t("Branch", doc.get("custom_location")) -%}
{%- set designation = t("Designation", doc.designation) -%}

{%- set exp_range = doc.get("custom_work_experience_range") -%}
{%- if not exp_range and (doc.get("custom_experience_range_from") or doc.get("custom_experience_range_to")) -%}
	{%- set exp_range = (doc.get("custom_experience_range_from") or "0") ~ " - " ~ (doc.get("custom_experience_range_to") or "") ~ " " ~ (doc.get("custom_experience_unit") or "years") -%}
{%- endif -%}

{%- set salary = doc.get("custom_salary_range_display") -%}
{%- if not salary and (doc.get("custom_salary_range_min") or doc.get("custom_salary_range_max")) -%}
	{%- set salary = (doc.get("custom_salary_range_currency") or "") ~ " " ~ (doc.get("custom_salary_range_min") or "") ~ " - " ~ (doc.get("custom_salary_range_max") or "") -%}
{%- endif -%}
{%- if salary and doc.get("custom_salary_timeframe") -%}
	{%- set salary = salary ~ " (" ~ doc.custom_salary_timeframe ~ ")" -%}
{%- endif -%}

<div class="jr">

	<div class="jr-head">
		<div class="jr-head-top">
			<div class="jr-head-left">
				<div class="jr-eyebrow">{{ doc.company or "" }}</div>
				<div class="jr-title">{{ designation or _("Job Requisition") }}</div>
				<div class="jr-subtitle">
					{{ _("Job Requisition") }}
					{%- if department %} &middot; {{ department }}{% endif -%}
					{%- if location %} &middot; {{ location }}{% endif -%}
				</div>
			</div>
			<div class="jr-head-right">
				<div class="jr-eyebrow">{{ _("Requisition No.") }}</div>
				<div class="jr-id">{{ doc.name }}</div>
				<div class="jr-pill {{ pill }}">{{ _(doc.status or "Draft") }}</div>
			</div>
		</div>
	</div>

	<table class="jr-stats">
		<tr>
			<td>
				<div class="jr-stat-value">{{ openings or 0 }}</div>
				<div class="jr-stat-label">{{ _("Openings") }}</div>
			</td>
			<td>
				<div class="jr-stat-value">{{ doc.get("custom_active_employees") or 0 }}</div>
				<div class="jr-stat-label">{{ _("Active Employees") }}</div>
			</td>
			<td>
				<div class="jr-stat-value">{{ doc.get("custom_active_openings") or 0 }}</div>
				<div class="jr-stat-label">{{ _("Hiring in Progress") }}</div>
			</td>
			<td>
				<div class="jr-stat-value">
					{%- if doc.expected_by -%}{{ frappe.utils.formatdate(doc.expected_by, "d MMM yyyy") }}{%- else -%}&mdash;{%- endif -%}
				</div>
				<div class="jr-stat-label">{{ _("Expected By") }}</div>
			</td>
		</tr>
	</table>

	<div class="jr-section">
		<div class="jr-section-title">{{ _("Request") }}</div>
		{{ grid([
			(_("Raised By"), requested_by),
			(_("Posting Date"), frappe.utils.formatdate(doc.posting_date) if doc.posting_date else ""),
			(_("Requester Department"), requester_dept),
			(_("Requester Designation"), t("Designation", doc.requested_by_designation)),
			(_("Hiring Lead"), hiring_lead),
			(_("Recruiter"), recruiter),
			(_("Expected By"), frappe.utils.formatdate(doc.expected_by) if doc.expected_by else ""),
			(_("Completed On"), frappe.utils.formatdate(doc.completed_on) if doc.completed_on else ""),
		]) }}
	</div>

	<div class="jr-section">
		<div class="jr-section-title">{{ _("Position") }}</div>
		{{ grid([
			(_("Designation"), designation),
			(_("Designation Alias"), doc.get("custom_designation_change")),
			(_("Department"), department),
			(_("Division"), t("Division", doc.get("custom_division"))),
			(_("Functional Area"), t("Functional Area", doc.get("custom_functional_area"))),
			(_("Location"), location),
			(_("Employment Type"), t("Employment Type", doc.get("custom_employment_type_link"))),
			(_("Hiring Type"), doc.get("custom_hiring_type")),
			(_("Cost Centre"), doc.get("custom_cost_centre")),
			(_("No. of Positions"), openings),
			(_("Preferred Notice Period"), doc.get("custom_preferred_notice_period")),
		]) }}
	</div>

	{%- set comp_pairs = [
		(_("Work Experience"), exp_range),
		(_("Salary Range"), salary),
		(_("Expected Compensation"), frappe.format_value(doc.expected_compensation, {"fieldtype": "Currency"}) if doc.expected_compensation else ""),
		(_("Fixed / Variable Pay"),
			((doc.get("fixed_pay") or 0) | string) ~ " / " ~ ((doc.get("variable_pay") or 0) | string)
			if (doc.get("fixed_pay") or doc.get("variable_pay")) else ""),
	] -%}
	{%- set has_comp = exp_range or salary or doc.expected_compensation or doc.get("fixed_pay") or doc.get("variable_pay") -%}
	{%- if has_comp -%}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Compensation & Experience") }}</div>
		{{ grid(comp_pairs) }}
	</div>
	{%- endif %}

	{% if regions %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Regions & Headcount") }}</div>
		<table class="jr-table">
			<thead>
				<tr>
					<th style="width: 34%">{{ _("Region") }}</th>
					<th class="jr-num">{{ _("Openings") }}</th>
					<th class="jr-num">{{ _("Active Employees") }}</th>
					<th class="jr-num">{{ _("Live Requisitions") }}</th>
					<th class="jr-num">{{ _("Hiring in Progress") }}</th>
				</tr>
			</thead>
			<tbody>
				{% for r in regions %}
				<tr>
					<td>{{ t("Region", r.region) }}</td>
					<td class="jr-num">{{ r.no_of_openings or 0 }}</td>
					<td class="jr-num">{{ r.active_employees or 0 }}</td>
					<td class="jr-num">{{ r.active_requisitions or 0 }}</td>
					<td class="jr-num">{{ r.active_openings or 0 }}</td>
				</tr>
				{% endfor %}
				<tr class="jr-total">
					<td>{{ _("Total") }}</td>
					<td class="jr-num">{{ tot.openings }}</td>
					<td class="jr-num">{{ tot.employees }}</td>
					<td class="jr-num">{{ tot.requisitions }}</td>
					<td class="jr-num">{{ tot.live }}</td>
				</tr>
			</tbody>
		</table>
	</div>
	{% endif %}

	{% if positions %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Vacancy Details") }}</div>
		<table class="jr-table">
			<thead>
				<tr>
					<th class="jr-center" style="width: 5%">#</th>
					<th>{{ _("Location") }}</th>
					<th>{{ _("Sub Location") }}</th>
					<th>{{ _("Reporting Manager") }}</th>
					<th>{{ _("Replacement For") }}</th>
					<th>{{ _("Employee Type") }}</th>
					<th class="jr-center">{{ _("Approval") }}</th>
				</tr>
			</thead>
			<tbody>
				{% for p in positions %}
				<tr>
					<td class="jr-center">{{ loop.index }}</td>
					<td>{{ t("Branch", p.location) }}</td>
					<td>{{ t("Sub Location", p.sub_location) }}</td>
					<td>{{ t("Employee", p.reporting_manager) }}</td>
					<td>{% if p.replacement_for %}{{ t("Employee", p.replacement_for) }}{% else %}<span class="jr-muted">{{ _("New Position") }}</span>{% endif %}</td>
					<td>{{ t("Employment Type", p.employee_type) }}</td>
					<td class="jr-center">{{ _(p.approval_status or "Pending") }}</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
	</div>
	{% endif %}

	{% if quals or skills %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Qualifications & Skills") }}</div>
		{% if quals %}
		<table class="jr-table"{% if skills %} style="margin-bottom: 7px"{% endif %}>
			<thead>
				<tr>
					<th style="width: 80%">{{ _("Qualification") }}</th>
					<th class="jr-center">{{ _("Mandatory") }}</th>
				</tr>
			</thead>
			<tbody>
				{% for q in quals %}
				<tr>
					<td>{{ q.qualification or "" }}</td>
					<td class="jr-center">{{ _(q.mandatory or "") }}</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
		{% endif %}
		{% if skills %}
		<div>
			{% for s in skills %}<span class="jr-chip">{{ t("Skill", s.skill) }}</span>{% endfor %}
		</div>
		{% endif %}
	</div>
	{% endif %}

	{% if doc.get("custom_preferred_company") or doc.get("custom_other_preferred_companies") %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Preferred Companies") }}</div>
		{% for c in doc.get("custom_preferred_company") or [] %}<span class="jr-chip">{{ t("Preferred Target Company", c.preferred_company) }}</span>{% endfor %}
		{% if doc.get("custom_other_preferred_companies") %}
		<div class="jr-prose jr-pre" style="margin-top: 4px">{{ doc.custom_other_preferred_companies }}</div>
		{% endif %}
	</div>
	{% endif %}

	{% if candidates %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Pre-Screened Candidates") }}</div>
		<table class="jr-table">
			<thead>
				<tr>
					<th class="jr-center" style="width: 5%">#</th>
					<th>{{ _("Name") }}</th>
					<th>{{ _("Email") }}</th>
					<th>{{ _("Phone") }}</th>
					<th class="jr-center">{{ _("Offer Directly") }}</th>
				</tr>
			</thead>
			<tbody>
				{% for c in candidates %}
				<tr>
					<td class="jr-center">{{ loop.index }}</td>
					<td>{{ c.candidate_name or "" }}</td>
					<td>{{ c.email or "" }}</td>
					<td>{{ c.phone or "" }}</td>
					<td class="jr-center">{{ _("Yes") if c.offer_directly else _("No") }}</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
	</div>
	{% endif %}

	{% if doc.reason_for_requesting or doc.get("custom_comments__instructions") %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Justification & Notes") }}</div>
		{% if doc.reason_for_requesting %}
		<div class="jr-prose jr-pre">{{ doc.reason_for_requesting }}</div>
		{% endif %}
		{% if doc.get("custom_comments__instructions") %}
		<div class="jr-prose jr-pre" style="margin-top: 6px">{{ doc.custom_comments__instructions }}</div>
		{% endif %}
	</div>
	{% endif %}

	{% if doc.get("custom_additional_roles__responsibilities") %}
	<div class="jr-section">
		<div class="jr-section-title">{{ _("Additional Roles & Responsibilities") }}</div>
		<div class="jr-prose jr-pre">{{ doc.custom_additional_roles__responsibilities }}</div>
	</div>
	{% endif %}

	{#- The JD can run for pages, so it goes last and is allowed to break across them. -#}
	{% if doc.description or jd_details %}
	<div class="jr-section jr-section-flow">
		<div class="jr-section-title">{{ _("Job Description") }}</div>
		{% if doc.description %}
		{#- the field takes both rich text and plain text; plain text needs its line breaks kept -#}
		<div class="{{ 'jr-rich' if '</' in doc.description else 'jr-prose jr-pre' }}">{{ doc.description }}</div>
		{% endif %}
		{% for d in jd_details %}
		{% if d.description %}
		<div style="margin-top: 6px">
			<div class="jr-label">{{ d.label or "" }}</div>
			<div class="jr-prose jr-pre">{{ d.description }}</div>
		</div>
		{% endif %}
		{% endfor %}
	</div>
	{% endif %}

	<table class="jr-sign">
		<tr>
			<td>
				<div class="jr-sign-role">{{ _("Raised By") }}</div>
				<div class="jr-sign-name">{{ requested_by or "&nbsp;" }}</div>
				<div class="jr-sign-line">{{ _("Signature & Date") }}</div>
			</td>
			<td>
				<div class="jr-sign-role">{{ _("Hiring Lead") }}</div>
				<div class="jr-sign-name">{{ hiring_lead or "&nbsp;" }}</div>
				<div class="jr-sign-line">{{ _("Signature & Date") }}</div>
			</td>
			<td>
				<div class="jr-sign-role">{{ _("Approved By") }}</div>
				<div class="jr-sign-name">&nbsp;</div>
				<div class="jr-sign-line">{{ _("Signature & Date") }}</div>
			</td>
		</tr>
	</table>

	<div class="jr-foot">
		<div class="jr-foot-left">
			{{ _("Job Requisition") }} {{ doc.name }}
			{%- if doc.get("custom_headcount_last_updated") %} &middot; {{ _("Headcount as on") }} {{ frappe.utils.format_datetime(doc.custom_headcount_last_updated, "d MMM y") }}{% endif -%}
		</div>
		<div class="jr-foot-right">{{ _("Printed on") }} {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</div>
	</div>

</div>
